// Command seed-site loads the embedded site catalogue seeds
// (db/seeds/site_docs_<lang>.json — one row per indexable page per UI locale,
// generated by org/apps/web/scripts/seed-site-pages.ts) into site_documents,
// then rebuilds the chapter and appendix landing rows from chapter_text and
// appendices.
//
// Both steps are full-replace within their own `source` scope, so re-running
// after regenerating the seeds is the content-update path.
package main

import (
	"context"
	"fmt"
	"log/slog"
	"os"

	"github.com/wikiSubmission/ws-backend/db"
)

func main() {
	ctx := context.Background()
	database, err := db.DbSetup()
	if err != nil {
		slog.Error("Database setup failed", slog.Any("error", err))
		os.Exit(1)
	}
	defer database.Close()

	seeded, err := database.SeedSiteDocuments(ctx)
	if err != nil {
		slog.Error("Site seed failed", slog.Any("error", err))
		os.Exit(1)
	}
	fmt.Printf("Seeded %d site page rows.\n", seeded)

	derived, err := database.RebuildDerivedSiteDocuments(ctx)
	if err != nil {
		slog.Error("Derived site rows failed", slog.Any("error", err))
		os.Exit(1)
	}
	fmt.Printf("Derived %d chapter/appendix rows.\n", derived)
}
